-- Start From Scratch vision flow: the member writes two beats per life area
-- ("what's going on now" and "unleash your imagination") as raw material.
-- Both are stored verbatim on the draft session so the depth gate, the board,
-- and the compose pass read the same words. Additive.
-- NOTE: supabase/COMPLETE_SCHEMA_DUMP.sql is regenerated by the user after apply.

-- 1. Raw beats per category.
ALTER TABLE public.vision_draft_session_category_text
  ADD COLUMN IF NOT EXISTS now_text text,
  ADD COLUMN IF NOT EXISTS dream_text text,
  ADD COLUMN IF NOT EXISTS now_at timestamptz,
  ADD COLUMN IF NOT EXISTS dream_at timestamptz,
  ADD COLUMN IF NOT EXISTS unknown_at timestamptz;

COMMENT ON COLUMN public.vision_draft_session_category_text.now_text IS
  'Member''s verbatim "what''s going on now" for this area (scratch flow).';
COMMENT ON COLUMN public.vision_draft_session_category_text.dream_text IS
  'Member''s verbatim "unleash your imagination" for this area (scratch flow).';
COMMENT ON COLUMN public.vision_draft_session_category_text.unknown_at IS
  'Set when the member marked this area "I don''t know yet"; counts as ready.';

-- 2. A draft session is either the VIVA chat or the scratch flow. One personal
--    draft slot exists, so the mode tells the Update tab where to resume.
ALTER TABLE public.vision_draft_sessions
  ADD COLUMN IF NOT EXISTS mode text NOT NULL DEFAULT 'chat';

ALTER TABLE public.vision_draft_sessions
  DROP CONSTRAINT IF EXISTS vision_draft_sessions_mode_check;
ALTER TABLE public.vision_draft_sessions
  ADD CONSTRAINT vision_draft_sessions_mode_check
  CHECK (mode = ANY (ARRAY['chat', 'scratch']));
